package com.portfolio.features.experience.controller; import com.portfolio.common.api.ApiResponse; import com.portfolio.features.experience.dto.*; import com.portfolio.features.experience.mapper.ExperienceMapper; import com.portfolio.features.experience.service.ExperienceService; import com.portfolio.features.user.service.UserService; import jakarta.validation.Valid; import java.util.*; import lombok.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/experiences") @RequiredArgsConstructor public class ExperienceController {private final ExperienceService service;private final UserService users;private final ExperienceMapper mapper;@GetMapping public ApiResponse<List<ExperienceResponse>> list(@AuthenticationPrincipal Jwt j){return ApiResponse.success("Experiences retrieved successfully.",service.list(users.synchronize(j)).stream().map(mapper::toResponse).toList());}@PostMapping public ApiResponse<ExperienceResponse> create(@AuthenticationPrincipal Jwt j,@Valid @RequestBody ExperienceRequest r){return ApiResponse.success("Experience created successfully.",mapper.toResponse(service.create(users.synchronize(j),r)));}@PutMapping("/{id}") public ApiResponse<ExperienceResponse> update(@AuthenticationPrincipal Jwt j,@PathVariable UUID id,@Valid @RequestBody ExperienceRequest r){return ApiResponse.success("Experience updated successfully.",mapper.toResponse(service.update(users.synchronize(j),id,r)));}@DeleteMapping("/{id}") public ApiResponse<Void> delete(@AuthenticationPrincipal Jwt j,@PathVariable UUID id){service.delete(users.synchronize(j),id);return ApiResponse.success("Experience deleted successfully.",null);}}
